export const LOVE_QUESTION_REGISTRY: Record<QuizDifficulty, { foundation: QuizQuestion[]; growth: QuizQuestion[]; mastery: QuizQuestion[]; }> = {
  easy: {
    foundation: LOVE_EASY_FOUNDATION,
    growth: LOVE_EASY_GROWTH,
    mastery: LOVE_EASY_MASTERY
  },
  medium: {
    foundation: LOVE_MEDIUM_FOUNDATION,
    growth: LOVE_MEDIUM_GROWTH,
    mastery: LOVE_MEDIUM_MASTERY
  },
  hard: {
    foundation: LOVE_HARD_FOUNDATION,
    growth: LOVE_HARD_GROWTH,
    mastery: LOVE_HARD_MASTERY
  },
};

export function getLoveStageQuestions(difficulty: QuizDifficulty, stage: 1 | 2 | 3): QuizQuestion[] {
  const diffKey = (difficulty || 'easy').toLowerCase() as QuizDifficulty;
  const stageMap = LOVE_QUESTION_REGISTRY[diffKey] || LOVE_QUESTION_REGISTRY.easy;
  if (stage === 1) return stageMap.foundation;
  if (stage === 2) return stageMap.growth;
  return stageMap.mastery;
}

export function getLoveLevelQuestions(difficulty: QuizDifficulty, level: number): QuizQuestion[] {
  const stage = level <= 10 ? 1 : level <= 20 ? 2 : 3;
  const stagePool = getLoveStageQuestions(difficulty, stage);
  const offset = (level - 1) % 10;
  const startIndex = offset * 5;
  return stagePool.slice(startIndex, startIndex + 5);
}
